maze = open("maze.txt").read().splitlines()
rows = [list(line) for line in maze]
from collections import deque
start = (1,1)
DIRS = [(-1,0),(1,0),(0,-1),(0,1)]
q = deque([start])
prev = {start: None}
while q:
    r,c = q.popleft()
    for dr,dc in DIRS:
        nr,nc = r+dr, c+dc
        if 0<=nr<len(rows) and 0<=nc<len(rows[nr]) and rows[nr][nc] != "#" and (nr,nc) not in prev:
            prev[(nr,nc)] = (r,c)
            q.append((nr,nc))

# print maze with reachable marked
for i,row in enumerate(rows):
    s=""
    for j,ch in enumerate(row):
        if ch=="#":
            s+="#"
        elif (i,j) in prev:
            s+="*" if ch!="@" else "@"
        else:
            s+=ch
    print(f"{i:2} {s}")

# Find walls that border both a reachable and unreachable open cell
print("--- bridge walls ---")
for i,row in enumerate(rows):
    for j,ch in enumerate(row):
        if ch != "#":
            continue
        neigh = []
        for dr,dc in DIRS:
            nr,nc=i+dr,j+dc
            if 0<=nr<len(rows) and 0<=nc<len(rows[nr]) and rows[nr][nc] != "#":
                neigh.append(((nr,nc), (nr,nc) in prev, rows[nr][nc]))
        reach = [n for n in neigh if n[1]]
        unreach = [n for n in neigh if not n[1]]
        if reach and unreach:
            print(i,j, "reach", reach, "unreach", unreach)
