from collections import deque
def analyze(path):
    rows=open(path).read().splitlines()
    g=[list(r) for r in rows]
    H,W=len(g),len(g[0])
    start=next((i,j) for i,r in enumerate(g) for j,c in enumerate(r) if c=="@")
    goal=next((i,j) for i,r in enumerate(g) for j,c in enumerate(r) if c=="E")
    def flood(src, blocked="#"):
        q=deque([src]); seen={src}
        while q:
            r,c=q.popleft()
            for dr,dc in ((-1,0),(1,0),(0,-1),(0,1)):
                nr,nc=r+dr,c+dc
                if 0<=nr<H and 0<=nc<W and g[nr][nc]!=blocked and (nr,nc) not in seen:
                    seen.add((nr,nc)); q.append((nr,nc))
        return seen
    S=flood(start); G=flood(goal)
    # min manhattan between components
    best=999; pair=None
    for a in S:
        for b in G:
            d=abs(a[0]-b[0])+abs(a[1]-b[1])
            if d<best:
                best=d; pair=(a,b)
    # also chebyshev
    bestc=999; pairc=None
    for a in S:
        for b in G:
            d=max(abs(a[0]-b[0]),abs(a[1]-b[1]))
            if d<bestc:
                bestc=d; pairc=(a,b)
    print(path, "start", start, "goal", goal, "manhattan", best, pair, "chebyshev", bestc, pairc, "sizes", len(S), len(G))

for p in ["maze.txt","../ep0/maze.txt","../ep1/maze.txt","../ep2/maze.txt","../ep4/maze.txt"]:
    analyze(p)
