from collections import deque
def gaps(path):
    rows=open(path).read().splitlines()
    g=[list(r) for r in rows]
    H,W=len(g),len(g[0])
    start=next((i,j) for i,r in enumerate(g) for j,c in enumerate(r) if c=="@")
    goal=next((i,j) for i,r in enumerate(g) for j,c in enumerate(r) if c=="E")
    def flood(src):
        q=deque([src]); seen={src}
        while q:
            r,c=q.popleft()
            for dr,dc in ((-1,0),(1,0),(0,-1),(0,1)):
                nr,nc=r+dr,c+dc
                if 0<=nr<H and 0<=nc<W and g[nr][nc]!="#" and (nr,nc) not in seen:
                    seen.add((nr,nc)); q.append((nr,nc))
        return seen
    S=flood(start); G=flood(goal)
    mids=set()
    for a in S:
        for b in G:
            if abs(a[0]-b[0])+abs(a[1]-b[1])==2 and (a[0]==b[0] or a[1]==b[1]):
                mids.add(((a[0]+b[0])//2,(a[1]+b[1])//2))
    return mids, (H,W), start, goal
for p in ["maze.txt","../ep0/maze.txt","../ep1/maze.txt","../ep2/maze.txt","../ep4/maze.txt"]:
