from collections import deque

def search(wrap=False, ignore_border=False):
    q=deque([start])
    prev={start:None}
    while q:
        r,c=q.popleft()
        if (r,c)==end:
            return True, len(prev)
        for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
