            ch=rows[nr][nc]
            if ignore_border and (nr==0 or nc==0 or nr==H-1 or nc==W-1):
                # border is walkable
                pass
            elif ch=="#":
                continue
            if (nr,nc) not in prev:
                prev[(nr,nc)]=(r,c)
                q.append((nr,nc))
    return False, len(prev)

print("normal", search())
print("wrap", search(wrap=True))
print("ignore border walls", search(ignore_border=True))

