import os
from collections import deque

def load(path):
    return open(path).read().splitlines()

def variants(rows):
    def fliph(r): return [x[::-1] for x in r]
    def flipv(r): return r[::-1]
    def rot90(r):
        H,W=len(r),len(r[0])
        return ["".join(r[H-1-rr][c] for rr in range(H)) for c in range(W)]
    out={"id":rows}
    out["h"]=fliph(rows)
    out["v"]=flipv(rows)
    out["180"]=fliph(flipv(rows))
    r=rows
    for k in range(1,4):
        r=rot90(r)
        out[f"rot{90*k}"]=r
    # rot + flip
    r=fliph(rows)
    for k in range(1,4):
        r=rot90(r)
        out[f"hrot{90*k}"]=r
    return out

def signature(rows):
    return "\n".join(r.replace("@",".").replace("E",".") for r in rows)

mazes={}
for ep in sorted(os.listdir("..")):
    p=os.path.join("..",ep,"maze.txt")
    if os.path.exists(p):
        mazes[ep]=load(p)

sigs={}
for ep,rows in mazes.items():
    for name,v in variants(rows).items():
        sigs.setdefault(signature(v), []).append(f"{ep}:{name}")

# print groups with more than one
for sig, names in sigs.items():
