def analyze(path):
    rows=open(path).read().splitlines()
    H,W=len(rows), len(rows[0])
    if H%2==0: 
        print(path, "even"); return
    centers=[(r,c) for r in range(1,H,2) for c in range(1,W,2)]
    adj=defaultdict(set)
    edges=0
    for r,c in centers:
