            nr,nc=r+dr,c+dc
            if nr>=H-1 or nc>=W-1: continue
            if rows[(r+nr)//2][(c+nc)//2] != "#":
                adj[(r,c)].add((nr,nc)); adj[(nr,nc)].add((r,c)); edges+=1
    cid={}; k=0
    for s in centers:
        if s in cid: continue
        q=deque([s]); cid[s]=k
        while q:
            u=q.popleft()
            for v in adj[u]:
                if v not in cid:
