    for i in range(k):
        mem=[c for c,v in cid.items() if v==i]
        e=sum(1 for u in mem for v in adj[u] if v>u)
        excesses.append((len(mem), e-(len(mem)-1)))
    print(f"{path}: size {H} centers {len(centers)} edges {edges} comps {k} excesses {excesses} expected_tree_edges {len(centers)-1}")

